Object.assign(SNIP,{});PRESET_NOTES["l23"]={"Ví dụ: 4 quân hậu, kiểm tra bằng cách nhìn lên các hàng trên": "Theo dõi bàn cờ: quân ở hàng 0 thử cột 0 trước; hàng 1 chỉ đặt được ở cột 2 hoặc 3; tới hàng 2 thì không còn cột nào, nên quay lui. Nghiệm đầu tiên xuất hiện khi hàng 0 đặt ở cột 1. Mỗi lần kiểm tra tốn O(n).", "Ví dụ: Kiểm tra O(1) bằng ba mảng đánh dấu": "Ô (r, c) có r + c và r − c + 3 là chỉ số đường chéo. Khi đặt quân ở (0, 1): cot[1], cheo1[1], cheo2[2] bật. Hai nghiệm in ra dạng cột của từng hàng: 1 3 0 2 và 2 0 3 1.", "Ví dụ: Đếm số nút khi không cắt và khi cắt nhánh": "Cùng ra 4 nghiệm, nhưng cách A đi qua 1 957 nút (đủ 720 hoán vị), cách B chỉ 153 nút. Với n = 8 tỉ lệ là 109 601 nút so với 2 057; n càng lớn, cắt nhánh càng lợi. Bấm Chạy để thấy hai bộ đếm tăng.", "Ví dụ: Nhánh cận, tổng lớn nhất không quá W": "Nhánh 8 + 5 đạt ngay 13 = W. Từ đó mọi nút có tong + conLai ≤ 13 bị cắt. Không có cận, cây có tới 2⁶ − 1 = 63 nút; ở đây chỉ còn 17 nút.", "Lỗi: quên kiểm tra một chiều đường chéo": "Bàn 4 × 4 chỉ có 2 nghiệm, nhưng chương trình đếm được 7 vì chấp nhận cả những cách có hai quân cùng đường chéo “\\”. Lỗi kiểu này không làm chương trình dừng: cách phát hiện là so với đáp án đã biết của n nhỏ (n = 4: 2, n = 8: 92)."};EX_HINTS["l23"]=[["Mỗi hàng đúng một quân: dat(r) chọn cột cho hàng r.", "Ba mảng đánh dấu: cot[c], cheo1[r + c], cheo2[r − c + n − 1].", "Đặt thì bật cả ba, sau lời gọi đệ quy thì tắt cả ba."], ["Thử cột theo thứ tự tăng dần thì nghiệm tìm thấy đầu tiên chính là nghiệm nhỏ nhất theo thứ tự từ điển.", "Cho hàm trả về bool: nếu lời gọi con trả về true thì trả về true ngay, không gỡ đánh dấu, không thử tiếp.", "Với n = 14, quay lui chỉ đi qua khoảng 1 900 nút trước khi gặp nghiệm đầu tiên."], ["Giống N quân hậu: ba bộ mảng đánh dấu hang[r][v], cot[c][v], khoi[b][v] cho biết số v đã có trong hàng, cột, khối chưa.", "Ô (r, c) thuộc khối b = r / 3 * 3 + c / 3. Ô đã có số sẵn thì bỏ qua: giai(k + 1).", "Đừng quên đánh dấu các số có sẵn trong đề trước khi gọi giai(0)."]];
/* ===================== BÀI 23 · Quay lui có cắt nhánh: bài toán N quân hậu ===================== */
/* Bài 23 · Quay lui có cắt nhánh: bài toán N quân hậu
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR23=[{label:"Ví dụ: 4 quân hậu, kiểm tra bằng cách nhìn lên các hàng trên",input:"",code:"#include <iostream>\nusing namespace std;\n\nint n = 4;\nint bang[4][4];   // 1: có quân hậu\n\nbool anToan(int r, int c) {\n    for (int i = 0; i < r; i++) {\n        int d = r - i;\n        if (bang[i][c]) return false;                      // cùng cột\n        if (c - d >= 0 && bang[i][c - d]) return false;     // chéo lên bên trái\n        if (c + d < n && bang[i][c + d]) return false;      // chéo lên bên phải\n    }\n    return true;\n}\n\nvoid dat(int r) {\n    if (r == n) {\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j < n; j++) cout << (bang[i][j] ? \"Q \" : \". \");\n            cout << \"\\n\";\n        }\n        cout << \"\\n\";\n        return;\n    }\n    for (int c = 0; c < n; c++) {\n        if (anToan(r, c)) {\n            bang[r][c] = 1;\n            dat(r + 1);\n            bang[r][c] = 0;     // gỡ quân để thử cột khác\n        }\n    }\n}\n\nint main() {\n    dat(0);\n    return 0;\n}",viz:[{type:"grid",of:"bang",cur:["r","c"],label:"bang"},{type:"calls"}],py:{code:"n = 4\nbang = [[0] * n for _ in range(n)]   # 1: có quân hậu\n\ndef anToan(r, c):\n    for i in range(r):\n        d = r - i\n        if bang[i][c]:                         # cùng cột\n            return False\n        if c - d >= 0 and bang[i][c - d]:      # chéo lên bên trái\n            return False\n        if c + d < n and bang[i][c + d]:       # chéo lên bên phải\n            return False\n    return True\n\ndef dat(r):\n    if r == n:\n        for hang in bang:\n            print(\" \".join(\"Q\" if v else \".\" for v in hang))\n        print()\n        return\n    for c in range(n):\n        if anToan(r, c):\n            bang[r][c] = 1\n            dat(r + 1)\n            bang[r][c] = 0     # gỡ quân để thử cột khác\n\ndat(0)"},cs:{code:"using System;\n\nclass Program\n{\n    static int n = 4;\n    static int[][] bang = new int[4][];   // 1: có quân hậu\n\n    static bool AnToan(int r, int c)\n    {\n        for (int i = 0; i < r; i++)\n        {\n            int d = r - i;\n            if (bang[i][c] == 1) return false;                      // cùng cột\n            if (c - d >= 0 && bang[i][c - d] == 1) return false;     // chéo lên bên trái\n            if (c + d < n && bang[i][c + d] == 1) return false;      // chéo lên bên phải\n        }\n        return true;\n    }\n\n    static void Dat(int r)\n    {\n        if (r == n)\n        {\n            for (int i = 0; i < n; i++)\n            {\n                for (int j = 0; j < n; j++) Console.Write(bang[i][j] == 1 ? \"Q \" : \". \");\n                Console.WriteLine();\n            }\n            Console.WriteLine();\n            return;\n        }\n        for (int c = 0; c < n; c++)\n        {\n            if (AnToan(r, c))\n            {\n                bang[r][c] = 1;\n                Dat(r + 1);\n                bang[r][c] = 0;     // gỡ quân để thử cột khác\n            }\n        }\n    }\n\n    static void Main()\n    {\n        for (int i = 0; i < n; i++) bang[i] = new int[n];\n        Dat(0);\n    }\n}"}},{label:"Ví dụ: Kiểm tra O(1) bằng ba mảng đánh dấu",input:"",code:"#include <iostream>\nusing namespace std;\n\nint n = 4;\nint x[4];                              // x[r]: cột của quân ở hàng r\nbool cot[4], cheo1[7], cheo2[7];       // 7 = 2n - 1 đường chéo mỗi chiều\n\nvoid dat(int r) {\n    if (r == n) {\n        for (int i = 0; i < n; i++) cout << x[i] << \" \";\n        cout << \"\\n\";\n        return;\n    }\n    for (int c = 0; c < n; c++) {\n        if (cot[c] || cheo1[r + c] || cheo2[r - c + n - 1]) continue;\n        x[r] = c;\n        cot[c] = cheo1[r + c] = cheo2[r - c + n - 1] = true;\n        dat(r + 1);\n        cot[c] = cheo1[r + c] = cheo2[r - c + n - 1] = false;\n    }\n}\n\nint main() {\n    dat(0);\n    return 0;\n}",viz:[{type:"cells",of:"x",ptr:["r"]},{type:"cells",of:"cot",ptr:["c"]},{type:"cells",of:"cheo1",ptr:["r+c"]},{type:"cells",of:"cheo2",ptr:["r-c+n-1"]}],py:{code:"n = 4\nx = [0] * n                    # x[r]: cột của quân ở hàng r\ncot = [False] * n\ncheo1 = [False] * (2 * n - 1)  # chỉ số r + c\ncheo2 = [False] * (2 * n - 1)  # chỉ số r - c + n - 1\n\ndef dat(r):\n    if r == n:\n        print(*x)\n        return\n    for c in range(n):\n        if cot[c] or cheo1[r + c] or cheo2[r - c + n - 1]:\n            continue\n        x[r] = c\n        cot[c] = cheo1[r + c] = cheo2[r - c + n - 1] = True\n        dat(r + 1)\n        cot[c] = cheo1[r + c] = cheo2[r - c + n - 1] = False\n\ndat(0)",note:"Ô (r, c) có r + c và r − c + 3 là chỉ số đường chéo. Python cho phép chỉ số âm (cheo2[-1] là ô cuối) nên viết r − c sẽ không báo lỗi mà chạy SAI âm thầm; luôn cộng n − 1. Hai nghiệm: 1 3 0 2 và 2 0 3 1."},cs:{code:"using System;\n\nclass Program\n{\n    static int n = 4;\n    static int[] x = new int[4];                       // x[r]: cột của quân ở hàng r\n    static bool[] cot = new bool[4], cheo1 = new bool[7], cheo2 = new bool[7];\n\n    static void Dat(int r)\n    {\n        if (r == n)\n        {\n            Console.WriteLine(string.Join(\" \", x));\n            return;\n        }\n        for (int c = 0; c < n; c++)\n        {\n            if (cot[c] || cheo1[r + c] || cheo2[r - c + n - 1]) continue;\n            x[r] = c;\n            cot[c] = cheo1[r + c] = cheo2[r - c + n - 1] = true;\n            Dat(r + 1);\n            cot[c] = cheo1[r + c] = cheo2[r - c + n - 1] = false;\n        }\n    }\n\n    static void Main()\n    {\n        Dat(0);\n    }\n}"}},{label:"Ví dụ: Đếm số nút khi không cắt và khi cắt nhánh",input:"",code:"#include <iostream>\nusing namespace std;\n\nint n = 6;\nint x[6];\nbool cot[6], cheo1[11], cheo2[11];\nint nutA = 0, nghiemA = 0, nutB = 0, nghiemB = 0;\n\n// A: chỉ giữ khác cột (sinh hoán vị), kiểm tra đường chéo khi đã đặt đủ\nvoid datA(int r) {\n    nutA++;\n    if (r == n) {\n        for (int i = 0; i < n; i++)\n            for (int j = i + 1; j < n; j++)\n                if (j - i == x[j] - x[i] || j - i == x[i] - x[j]) return;\n        nghiemA++;\n        return;\n    }\n    for (int c = 0; c < n; c++) {\n        if (cot[c]) continue;\n        cot[c] = true; x[r] = c;\n        datA(r + 1);\n        cot[c] = false;\n    }\n}\n\n// B: kiểm tra cả đường chéo ngay khi đặt\nvoid datB(int r) {\n    nutB++;\n    if (r == n) { nghiemB++; return; }\n    for (int c = 0; c < n; c++) {\n        if (cot[c] || cheo1[r + c] || cheo2[r - c + n - 1]) continue;\n        cot[c] = cheo1[r + c] = cheo2[r - c + n - 1] = true;\n        datB(r + 1);\n        cot[c] = cheo1[r + c] = cheo2[r - c + n - 1] = false;\n    }\n}\n\nint main() {\n    datA(0);\n    datB(0);\n    cout << \"Khong cat: \" << nutA << \" nut, \" << nghiemA << \" nghiem\\n\";\n    cout << \"Cat nhanh: \" << nutB << \" nut, \" << nghiemB << \" nghiem\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["nutA","nghiemA","nutB","nghiemB"]}],py:{code:"n = 6\nx = [0] * n\ncot = [False] * n\ncheo1 = [False] * (2 * n - 1)\ncheo2 = [False] * (2 * n - 1)\nnutA = nghiemA = nutB = nghiemB = 0\n\n# A: chỉ giữ khác cột (sinh hoán vị), kiểm tra đường chéo khi đã đặt đủ\ndef datA(r):\n    global nutA, nghiemA\n    nutA += 1\n    if r == n:\n        for i in range(n):\n            for j in range(i + 1, n):\n                if j - i == abs(x[j] - x[i]):\n                    return\n        nghiemA += 1\n        return\n    for c in range(n):\n        if cot[c]:\n            continue\n        cot[c] = True\n        x[r] = c\n        datA(r + 1)\n        cot[c] = False\n\n# B: kiểm tra cả đường chéo ngay khi đặt\ndef datB(r):\n    global nutB, nghiemB\n    nutB += 1\n    if r == n:\n        nghiemB += 1\n        return\n    for c in range(n):\n        if cot[c] or cheo1[r + c] or cheo2[r - c + n - 1]:\n            continue\n        cot[c] = cheo1[r + c] = cheo2[r - c + n - 1] = True\n        datB(r + 1)\n        cot[c] = cheo1[r + c] = cheo2[r - c + n - 1] = False\n\ndatA(0)\ndatB(0)\nprint(f\"Khong cat: {nutA} nut, {nghiemA} nghiem\")\nprint(f\"Cat nhanh: {nutB} nut, {nghiemB} nghiem\")"},cs:{code:"using System;\n\nclass Program\n{\n    static int n = 6;\n    static int[] x = new int[6];\n    static bool[] cot = new bool[6], cheo1 = new bool[11], cheo2 = new bool[11];\n    static int nutA = 0, nghiemA = 0, nutB = 0, nghiemB = 0;\n\n    // A: chỉ giữ khác cột (sinh hoán vị), kiểm tra đường chéo khi đã đặt đủ\n    static void DatA(int r)\n    {\n        nutA++;\n        if (r == n)\n        {\n            for (int i = 0; i < n; i++)\n                for (int j = i + 1; j < n; j++)\n                    if (j - i == Math.Abs(x[j] - x[i])) return;\n            nghiemA++;\n            return;\n        }\n        for (int c = 0; c < n; c++)\n        {\n            if (cot[c]) continue;\n            cot[c] = true; x[r] = c;\n            DatA(r + 1);\n            cot[c] = false;\n        }\n    }\n\n    // B: kiểm tra cả đường chéo ngay khi đặt\n    static void DatB(int r)\n    {\n        nutB++;\n        if (r == n) { nghiemB++; return; }\n        for (int c = 0; c < n; c++)\n        {\n            if (cot[c] || cheo1[r + c] || cheo2[r - c + n - 1]) continue;\n            cot[c] = cheo1[r + c] = cheo2[r - c + n - 1] = true;\n            DatB(r + 1);\n            cot[c] = cheo1[r + c] = cheo2[r - c + n - 1] = false;\n        }\n    }\n\n    static void Main()\n    {\n        DatA(0);\n        DatB(0);\n        Console.WriteLine($\"Khong cat: {nutA} nut, {nghiemA} nghiem\");\n        Console.WriteLine($\"Cat nhanh: {nutB} nut, {nghiemB} nghiem\");\n    }\n}"}},{label:"Ví dụ: Nhánh cận, tổng lớn nhất không quá W",input:"",code:"#include <iostream>\nusing namespace std;\n\nint a[5] = {8, 6, 5, 4, 3};   // đã sắp giảm dần\nint n = 5, W = 13;\nint conLai[6];                // conLai[i] = a[i] + ... + a[n - 1]\nint kyLuc = 0, nut = 0;\n\nvoid thu(int i, int tong) {\n    nut++;\n    if (tong > kyLuc) kyLuc = tong;\n    if (i == n) return;\n    if (tong + conLai[i] <= kyLuc) return;     // cận: lấy hết cũng không hơn kỷ lục\n    if (tong + a[i] <= W) thu(i + 1, tong + a[i]);\n    thu(i + 1, tong);\n}\n\nint main() {\n    for (int i = n - 1; i >= 0; i--) conLai[i] = conLai[i + 1] + a[i];\n    thu(0, 0);\n    cout << kyLuc << \" (\" << nut << \" nut)\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i"]},{type:"vars",names:["tong","kyLuc","nut"]},{type:"calls"}],py:{code:"a = [8, 6, 5, 4, 3]   # đã sắp giảm dần\nn, W = 5, 13\nconLai = [0] * (n + 1)          # conLai[i] = a[i] + ... + a[n - 1]\nfor i in range(n - 1, -1, -1):\n    conLai[i] = conLai[i + 1] + a[i]\nkyLuc = nut = 0\n\ndef thu(i, tong):\n    global kyLuc, nut\n    nut += 1\n    kyLuc = max(kyLuc, tong)\n    if i == n:\n        return\n    if tong + conLai[i] <= kyLuc:        # cận: lấy hết cũng không hơn kỷ lục\n        return\n    if tong + a[i] <= W:\n        thu(i + 1, tong + a[i])\n    thu(i + 1, tong)\n\nthu(0, 0)\nprint(f\"{kyLuc} ({nut} nut)\")"},cs:{code:"using System;\n\nclass Program\n{\n    static int[] a = { 8, 6, 5, 4, 3 };   // đã sắp giảm dần\n    static int n = 5, W = 13;\n    static int[] conLai = new int[6];     // conLai[i] = a[i] + ... + a[n - 1]\n    static int kyLuc = 0, nut = 0;\n\n    static void Thu(int i, int tong)\n    {\n        nut++;\n        if (tong > kyLuc) kyLuc = tong;\n        if (i == n) return;\n        if (tong + conLai[i] <= kyLuc) return;     // cận: lấy hết cũng không hơn kỷ lục\n        if (tong + a[i] <= W) Thu(i + 1, tong + a[i]);\n        Thu(i + 1, tong);\n    }\n\n    static void Main()\n    {\n        for (int i = n - 1; i >= 0; i--) conLai[i] = conLai[i + 1] + a[i];\n        Thu(0, 0);\n        Console.WriteLine($\"{kyLuc} ({nut} nut)\");\n    }\n}"}},{label:"Lỗi: quên kiểm tra một chiều đường chéo",input:"",code:"#include <iostream>\nusing namespace std;\n\nint n = 4, dem = 0;\nbool cot[4], cheo1[7];\n\nvoid dat(int r) {\n    if (r == n) { dem++; return; }\n    for (int c = 0; c < n; c++) {\n        if (cot[c] || cheo1[r + c]) continue;     // thiếu: đường chéo r - c\n        cot[c] = cheo1[r + c] = true;\n        dat(r + 1);\n        cot[c] = cheo1[r + c] = false;\n    }\n}\n\nint main() {\n    dat(0);\n    cout << dem << \" nghiem\\n\";\n    return 0;\n}",py:{code:"n = 4\ndem = 0\ncot = [False] * n\ncheo1 = [False] * (2 * n - 1)\n\ndef dat(r):\n    global dem\n    if r == n:\n        dem += 1\n        return\n    for c in range(n):\n        if cot[c] or cheo1[r + c]:     # thiếu: đường chéo r - c\n            continue\n        cot[c] = cheo1[r + c] = True\n        dat(r + 1)\n        cot[c] = cheo1[r + c] = False\n\ndat(0)\nprint(dem, \"nghiem\")"},cs:{code:"using System;\n\nclass Program\n{\n    static int n = 4, dem = 0;\n    static bool[] cot = new bool[4], cheo1 = new bool[7];\n\n    static void Dat(int r)\n    {\n        if (r == n) { dem++; return; }\n        for (int c = 0; c < n; c++)\n        {\n            if (cot[c] || cheo1[r + c]) continue;     // thiếu: đường chéo r - c\n            cot[c] = cheo1[r + c] = true;\n            Dat(r + 1);\n            cot[c] = cheo1[r + c] = false;\n        }\n    }\n\n    static void Main()\n    {\n        Dat(0);\n        Console.WriteLine(dem + \" nghiem\");\n    }\n}"}}];
