makeEx2(document.getElementById("ex-l23"),sim23,[{t:"Đếm số cách đặt N quân hậu",d:"Đầu vào: n (1 ≤ n ≤ 8). Đầu ra: số cách đặt n quân hậu lên bàn n × n sao cho không có hai quân nào ăn nhau.",tests:[{in:"4",out:"2"},{in:"1",out:"1"},{in:"2",out:"0"},{in:"3",out:"0"},{in:"5",out:"10"},{in:"6",out:"4"},{in:"7",out:"40"},{in:"8",out:"92"}],start:"#include <iostream>\nusing namespace std;\n\nint n, dem = 0;\nbool cot[8], cheo1[15], cheo2[15];\n\nvoid dat(int r) {\n    // đặt quân ở hàng r vào một cột c an toàn, rồi gọi dat(r + 1)\n}\n\nint main() {\n    cin >> n;\n    dat(0);\n    cout << dem << \"\\n\";\n    return 0;\n}",py:{start:"n = int(input())\ndem = 0\ncot = [False] * n\ncheo1 = [False] * (2 * n - 1)\ncheo2 = [False] * (2 * n - 1)\n\ndef dat(r):\n    # đặt quân ở hàng r vào một cột c an toàn, rồi gọi dat(r + 1)\n    pass\n\ndat(0)\nprint(dem)",hints:["Mỗi hàng đúng một quân: dat(r) chọn cột cho hàng r.","Ba list đánh dấu: cot[c], cheo1[r + c], cheo2[r − c + n − 1]. Hàm sửa biến đếm toàn cục phải khai báo global dem.","Đặt thì bật cả ba, sau lời gọi đệ quy thì tắt cả ba."]},cs:{start:"using System;\n\nclass Program\n{\n    static int n, dem = 0;\n    static bool[] cot = new bool[8], cheo1 = new bool[15], cheo2 = new bool[15];\n\n    static void Dat(int r)\n    {\n        // đặt quân ở hàng r vào một cột c an toàn, rồi gọi Dat(r + 1)\n    }\n\n    static void Main()\n    {\n        n = int.Parse(Console.ReadLine());\n        Dat(0);\n        Console.WriteLine(dem);\n    }\n}",hints:["Mỗi hàng đúng một quân: Dat(r) chọn cột cho hàng r.","Ba mảng đánh dấu: cot[c], cheo1[r + c], cheo2[r − c + n − 1].","Đặt thì bật cả ba, sau lời gọi đệ quy thì tắt cả ba."]}},{t:"Nghiệm đầu tiên của N quân hậu",d:"Đầu vào: n (1 ≤ n ≤ 14). Đầu ra: nghiệm nhỏ nhất theo thứ tự từ điển, dạng n số trên một dòng: số thứ r là cột (đánh số từ 1) của quân ở hàng r. Nếu không có nghiệm, in -1. Chú ý: n = 14 có 365 596 nghiệm; phải <b>dừng ngay<\/b> khi tìm thấy nghiệm đầu tiên.",tests:[{in:"4",out:"2 4 1 3"},{in:"1",out:"1"},{in:"3",out:"-1"},{in:"8",out:"1 5 8 6 3 7 2 4"},{in:"12",out:"1 3 5 8 10 12 6 11 2 7 9 4"},{in:"14",out:"1 3 5 7 12 10 13 4 14 9 2 6 8 11"},{in:"2",out:"-1"}],start:"#include <iostream>\nusing namespace std;\n\nint n;\nint x[14];\nbool cot[14], cheo1[27], cheo2[27];\n\n// trả về true nếu đặt được hàng r..n-1; khi đó x chứa nghiệm\nbool dat(int r) {\n    return false;\n}\n\nint main() {\n    cin >> n;\n    if (dat(0)) {\n        for (int i = 0; i < n; i++) cout << x[i] + 1 << \" \";\n        cout << \"\\n\";\n    } else {\n        cout << -1 << \"\\n\";\n    }\n    return 0;\n}",py:{start:"n = int(input())\nx = [0] * n\ncot = [False] * n\ncheo1 = [False] * (2 * n - 1)\ncheo2 = [False] * (2 * n - 1)\n\n# trả về True nếu đặt được hàng r..n-1; khi đó x chứa nghiệm\ndef dat(r):\n    return False\n\nif dat(0):\n    print(*[c + 1 for c in x])\nelse:\n    print(-1)",hints:["Thử cột theo thứ tự tăng dần thì nghiệm tìm thấy đầu tiên chính là nghiệm nhỏ nhất theo thứ tự từ điển.","Cho hàm trả về True/False: nếu lời gọi con trả về True thì trả về True ngay, không thử tiếp.","Với n = 14, quay lui chỉ đi qua khoảng 1 900 nút trước khi gặp nghiệm đầu tiên."]},cs:{start:"using System;\n\nclass Program\n{\n    static int n;\n    static int[] x = new int[14];\n    static bool[] cot = new bool[14], cheo1 = new bool[27], cheo2 = new bool[27];\n\n    // trả về true nếu đặt được hàng r..n-1; khi đó x chứa nghiệm\n    static bool Dat(int r)\n    {\n        return false;\n    }\n\n    static void Main()\n    {\n        n = int.Parse(Console.ReadLine());\n        if (Dat(0))\n        {\n            for (int i = 0; i < n; i++) Console.Write(x[i] + 1 + \" \");\n            Console.WriteLine();\n        }\n        else\n        {\n            Console.WriteLine(-1);\n        }\n    }\n}",hints:["Thử cột theo thứ tự tăng dần thì nghiệm tìm thấy đầu tiên chính là nghiệm nhỏ nhất theo thứ tự từ điển.","Cho hàm trả về bool: nếu lời gọi con trả về true thì trả về true ngay, không thử tiếp.","Với n = 14, quay lui chỉ đi qua khoảng 1 900 nút trước khi gặp nghiệm đầu tiên."]}},{t:"Giải Sudoku",d:"Đầu vào: 9 dòng, mỗi dòng 9 chữ số viết liền; chữ số 0 là ô trống. Đầu ra: bảng đã điền, cùng định dạng, sao cho mỗi hàng, mỗi cột và mỗi khối 3 × 3 chứa đủ các số 1..9. Đề bảo đảm có đúng một cách điền.",tests:[{in:"504800302\n932000860\n087092104\n840736219\n109485736\n376200405\n060041070\n491500600\n750003040",out:"514867392\n932154867\n687392154\n845736219\n129485736\n376219485\n263941578\n491578623\n758623941"},{in:"007080390\n608309047\n900000508\n705038001\n001050680\n063902475\n309200006\n500800200\n100065830",out:"417586392\n658329147\n932174568\n745638921\n291457683\n863912475\n389241756\n576893214\n124765839"},{in:"024000059\n000900043\n080002070\n791083624\n000710085\n030000010\n009004060\n003260090\n070190038",out:"324671859\n617958243\n985342176\n791583624\n462719385\n538426917\n159834762\n843267591\n276195438"},{in:"010900000\n006000054\n020001006\n800030600\n065000023\n203000700\n008420001\n450019000\n691000540",out:"514968237\n986372154\n327541896\n879234615\n165897423\n243156789\n738425961\n452619378\n691783542"},{in:"206008010\n400326008\n000000000\n027000003\n040080000\n051460807\n000005304\n180004000\n004602000",out:"236758419\n419326578\n578149236\n827591643\n643287951\n951463827\n762815394\n185934762\n394672185"}],start:"#include <iostream>\n#include <string>\nusing namespace std;\n\nint a[9][9];\nbool hang[9][10], cot[9][10], khoi[9][10];   // khoi: khối 3x3 số r / 3 * 3 + c / 3\n\n// điền các ô từ ô thứ k (đánh số 0..80 theo hàng); trả về true nếu điền xong\nbool giai(int k) {\n    return false;\n}\n\nint main() {\n    for (int r = 0; r < 9; r++) {\n        string s;\n        cin >> s;\n        for (int c = 0; c < 9; c++) {\n            a[r][c] = s[c] - '0';\n            // nhớ đánh dấu các số đã có sẵn\n        }\n    }\n    giai(0);\n    for (int r = 0; r < 9; r++) {\n        for (int c = 0; c < 9; c++) cout << a[r][c];\n        cout << \"\\n\";\n    }\n    return 0;\n}",py:{start:"a = [[int(ch) for ch in input()] for _ in range(9)]\nhang = [[False] * 10 for _ in range(9)]\ncot = [[False] * 10 for _ in range(9)]\nkhoi = [[False] * 10 for _ in range(9)]   # khối 3x3 số r // 3 * 3 + c // 3\n# nhớ đánh dấu các số đã có sẵn\n\n# điền các ô từ ô thứ k (đánh số 0..80 theo hàng); trả về True nếu điền xong\ndef giai(k):\n    return False\n\ngiai(0)\nfor hangSo in a:\n    print(\"\".join(map(str, hangSo)))",hints:["Giống N quân hậu: ba bảng đánh dấu hang[r][v], cot[c][v], khoi[b][v] cho biết số v đã có trong hàng, cột, khối chưa.","Ô (r, c) thuộc khối b = r // 3 * 3 + c // 3; divmod(k, 9) cho cùng lúc r và c. Ô đã có số sẵn thì bỏ qua: giai(k + 1).","Đừng quên đánh dấu các số có sẵn trong đề trước khi gọi giai(0). Độ sâu đệ quy tối đa 82, không vượt giới hạn của Python."]},cs:{start:"using System;\n\nclass Program\n{\n    static int[][] a = new int[9][];\n    static bool[][] hang = new bool[9][], cot = new bool[9][], khoi = new bool[9][];   // khoi: khối r / 3 * 3 + c / 3\n\n    // điền các ô từ ô thứ k (đánh số 0..80 theo hàng); trả về true nếu điền xong\n    static bool Giai(int k)\n    {\n        return false;\n    }\n\n    static void Main()\n    {\n        for (int i = 0; i < 9; i++)\n        {\n            a[i] = new int[9];\n            hang[i] = new bool[10]; cot[i] = new bool[10]; khoi[i] = new bool[10];\n        }\n        for (int r = 0; r < 9; r++)\n        {\n            string s = Console.ReadLine();\n            for (int c = 0; c < 9; c++)\n            {\n                a[r][c] = s[c] - '0';\n                // nhớ đánh dấu các số đã có sẵn\n            }\n        }\n        Giai(0);\n        for (int r = 0; r < 9; r++) Console.WriteLine(string.Join(\"\", a[r]));\n    }\n}",hints:["Giống N quân hậu: ba bảng đánh dấu hang[r][v], cot[c][v], khoi[b][v] cho biết số v đã có trong hàng, cột, khối chưa.","Ô (r, c) thuộc khối b = r / 3 * 3 + c / 3. Ô đã có số sẵn thì bỏ qua: Giai(k + 1).","Đừng quên đánh dấu các số có sẵn trong đề trước khi gọi Giai(0)."]}}]);

makeQuiz("quiz23","score23",[{"q": "Vì sao chỉ số đường chéo “\\” viết là r − c + n − 1 thay vì r − c?", "o": ["Để chạy nhanh hơn", "Vì r − c có thể âm, không dùng làm chỉ số mảng được", "Vì r − c trùng với r + c", "Không có lý do"], "a": 1, "e": "r − c chạy từ −(n − 1) tới n − 1; cộng n − 1 đưa về 0..2n − 2."}, {"q": "Hai ô (2, 5) và (4, 3) có cùng đường chéo không?", "o": ["Không", "Có, cùng r + c = 7", "Có, cùng r − c", "Chỉ khi n = 8"], "a": 1, "e": "2 + 5 = 4 + 3 = 7: cùng một đường chéo “/”."}, {"q": "Cắt nhánh trong quay lui là gì?", "o": ["Dừng chương trình khi tìm được nghiệm", "Bỏ cả một cây con ngay khi biết nó không thể chứa lời giải (hoặc lời giải tốt hơn)", "Xóa các nghiệm trùng", "Giảm độ sâu đệ quy bằng vòng lặp"], "a": 1, "e": "Kiểm tra càng sớm, càng nhiều nút không bao giờ phải sinh ra."}, {"q": "Tìm tổng lớn nhất ≤ W, kỷ lục đang là 50. Nút hiện tại có tong = 30, tổng các số chưa xét là 15. Nên làm gì?", "o": ["Đi tiếp vì có thể tốt hơn", "Bỏ nhánh này: lấy hết cũng chỉ được 45 ≤ 50", "Đặt kỷ lục = 45", "Quay về gốc"], "a": 1, "e": "Cận trên 30 + 15 = 45 không vượt kỷ lục 50."}]);

